/**
 * AI Guardrail browser demo
 *
 * Sample reports are generated by the Python pipeline and stored as committed
 * JSON files. Custom reports are parsed and classified in this browser tab.
 */
(function () {
  "use strict"

  const REPORT_KEYS = ["sarif", "brakeman", "semgrep", "sonar", "cppcheck"]
  const SAMPLE_FILES = {
    sarif: "sample.sarif",
    brakeman: "brakeman.sarif",
    semgrep: "semgrep.sarif",
    sonar: "sonar.json",
    cppcheck: "cppcheck.xml"
  }
  let complianceIndex = null
  let reportBaseUrl = ""
  let sampleBaseUrl = ""
  let sampleRawText = ""
  let sampleLoadId = 0
  let pipelineRunId = 0
  let renderer = null

  function ready(fn) {
    if (document.readyState !== "loading") {
      fn()
    } else {
      document.addEventListener("DOMContentLoaded", fn)
    }
  }

  function normalizeCwe(cwe) {
    if (!cwe) return ""
    const value = String(cwe).trim().toUpperCase()
    return value.startsWith("CWE-") ? value : /^\d+$/.test(value) ? `CWE-${value}` : value
  }

  function buildComplianceIndex(rules) {
    const index = new Map()
    for (const [framework, frameworkRules] of Object.entries(rules)) {
      for (const [ruleId, rule] of Object.entries(frameworkRules)) {
        for (const cwe of rule.cwes || []) {
          const key = normalizeCwe(cwe)
          if (!index.has(key)) index.set(key, [])
          index.get(key).push({
            framework,
            ruleId,
            title: rule.title,
            description: rule.description
          })
        }
      }
    }
    return index
  }

  function complianceHitsForCwe(cwe) {
    return complianceIndex?.get(normalizeCwe(cwe)) || []
  }

  function parseReport(text, format) {
    const trimmed = text.trim()
    if (!trimmed) throw new Error("Please provide report content to run triage.")

    try {
      if (format === "cppcheck" || trimmed.startsWith("<")) return parseCppcheck(text)
      const data = JSON.parse(text)
      if (format === "sarif" || data.runs) return parseSarif(data)
      if (format === "sonar" || data.issues) return parseSonar(data)
      throw new Error("Unrecognized report structure. Use SARIF, SonarQube JSON, or cppcheck XML.")
    } catch (error) {
      if (error instanceof SyntaxError) {
        throw new Error("Could not parse report. Please check the JSON syntax.")
      }
      throw error
    }
  }

  function parseSarif(data) {
    const findings = []
    for (const run of data.runs || []) {
      for (const result of run.results || []) {
        const physical = result.locations?.[0]?.physicalLocation || {}
        const region = physical.region || {}
        findings.push({
          ruleId: result.ruleId || "unknown",
          message: result.message?.text || "",
          filePath: physical.artifactLocation?.uri || "",
          line: region.startLine || 0,
          column: region.startColumn || 0,
          severity: result.level === "error" ? "HIGH" : result.level === "warning" ? "MEDIUM" : "LOW",
          cwe: result.ruleId?.startsWith("CWE-") ? result.ruleId : null,
          tool: "sarif"
        })
      }
    }
    return findings
  }

  function parseSonar(data) {
    return (data.issues || []).map((issue) => ({
      ruleId: issue.rule || "unknown",
      message: issue.message || "",
      filePath: issue.component || "",
      line: issue.line || 0,
      column: 0,
      severity: issue.severity === "BLOCKER" || issue.severity === "CRITICAL" ? "HIGH" : issue.severity === "MAJOR" ? "MEDIUM" : "LOW",
      cwe: issue.cwes?.[0] ? normalizeCwe(issue.cwes[0]) : null,
      tool: "sonar"
    }))
  }

  function parseCppcheck(xmlText) {
    const document = new DOMParser().parseFromString(xmlText, "application/xml")
    if (document.querySelector("parsererror")) {
      throw new Error("Could not parse report. Please check the XML syntax.")
    }

    return [...document.querySelectorAll("error")].map((error) => {
      const location = error.querySelector("location")
      const severity = error.getAttribute("severity")
      return {
        ruleId: error.getAttribute("id") || "unknown",
        message: error.getAttribute("msg") || "",
        filePath: location?.getAttribute("file") || "",
        line: Number.parseInt(location?.getAttribute("line") || "0", 10),
        column: Number.parseInt(location?.getAttribute("column") || "0", 10),
        severity: severity === "error" ? "HIGH" : severity === "warning" ? "MEDIUM" : "LOW",
        cwe: error.getAttribute("cwe") ? `CWE-${error.getAttribute("cwe")}` : null,
        tool: "cppcheck"
      }
    })
  }

  function inferCwe(finding) {
    if (finding.cwe) return finding.cwe
    const text = `${finding.ruleId} ${finding.message}`.toUpperCase()
    const signals = [
      ["BUFFER", "CWE-121"],
      ["OVERFLOW", "CWE-121"],
      ["STRCPY", "CWE-121"],
      ["SQL", "CWE-89"],
      ["INJECTION", "CWE-89"],
      ["EVAL", "CWE-94"],
      ["JWT", "CWE-327"],
      ["CRYPTO", "CWE-327"],
      ["DOUBLE", "CWE-415"],
      ["FREE", "CWE-415"],
      ["UNINIT", "CWE-457"],
      ["HARDCODED", "CWE-798"],
      ["SECRET", "CWE-798"],
      ["REGEX", "CWE-1333"],
      ["RANDOM", "CWE-338"]
    ]
    return signals.find(([signal]) => text.includes(signal))?.[1] || null
  }

  function classifyFinding(finding) {
    const text = `${finding.ruleId} ${finding.message}`.toLowerCase()
    const cwe = normalizeCwe(finding.cwe)
    const highCwes = ["CWE-79", "CWE-89", "CWE-94", "CWE-119", "CWE-120", "CWE-121", "CWE-122", "CWE-125", "CWE-190", "CWE-327", "CWE-415", "CWE-416", "CWE-590", "CWE-787", "CWE-798"]
    const falsePositiveWords = ["unused", "unreachable", "style", "dead store", "redundant", "informational", "cosmetic"]
    const highWords = ["overflow", "buffer", "strcpy", "memcpy", "use-after-free", "double free", "injection", "eval", "jwt", "hardcoded", "secret", "md5", "weak", "unscoped", "authorization", "uninitialized"]

    if (highCwes.includes(cwe) || highWords.some((word) => text.includes(word))) {
      return {
        verdict: "HIGH_PRIORITY",
        confidence: 0.93,
        reasoning: "The finding matches a memory-safety, injection, or credential-handling signal.",
        remediation: "Validate inputs, replace unsafe operations, and add a targeted regression test."
      }
    }
    if (falsePositiveWords.some((word) => text.includes(word))) {
      return {
        verdict: "FALSE_POSITIVE",
        confidence: 0.88,
        reasoning: "The warning appears stylistic or refers to an unused symbol.",
        remediation: "Remove the unused element or document why it is intentional."
      }
    }
    return {
      verdict: "UNCLEAR",
      confidence: 0.64,
      reasoning: "The available report context is not enough for a confident decision.",
      remediation: "Review the finding manually and document the result."
    }
  }

  function runTriage(findings) {
    return findings.map((finding) => {
      finding.cwe = inferCwe(finding)
      return {
        finding,
        complianceHits: complianceHitsForCwe(finding.cwe),
        ...classifyFinding(finding)
      }
    })
  }

  function setStatus(message, isError = false) {
    const element = document.getElementById("guardrail-status")
    element.textContent = message
    element.className = `guardrail-status${isError ? " status-error" : " status-info"}`
    element.style.display = message ? "block" : "none"
  }

  function setPipelineStep(step, label) {
    const order = { parse: 0, context: 1, compliance: 2, classify: 3, report: 4 }
    document.querySelectorAll(".pipeline-step").forEach((element) => {
      element.classList.remove("active", "complete")
      if (order[element.dataset.step] < order[step]) element.classList.add("complete")
      if (element.dataset.step === step) element.classList.add("active")
    })
    document.getElementById("pipeline-status-text").textContent = label
  }

  function resetPipeline() {
    document.querySelectorAll(".pipeline-step").forEach((element) => element.classList.remove("active", "complete"))
    document.getElementById("pipeline-status-text").textContent = "Ready. Choose a sample or add custom input."
  }

  function normalizeResults(results) {
    return {
      summary: {
        total: results.length,
        high_priority: results.filter((result) => result.verdict === "HIGH_PRIORITY").length,
        false_positive: results.filter((result) => result.verdict === "FALSE_POSITIVE").length,
        unclear: results.filter((result) => result.verdict === "UNCLEAR").length
      },
      results: results.map((result) => ({
        finding: result.finding,
        verdict: result.verdict,
        confidence: result.confidence,
        reasoning: result.reasoning,
        remediation: result.remediation,
        compliance_hits: result.complianceHits
      }))
    }
  }

  function clearRenderedResults() {
    if (renderer) {
      renderer.destroy()
      renderer = null
    }
    document.getElementById("guardrail-results-panel").style.display = "none"
    document.getElementById("guardrail-empty-state").style.display = "block"
    document.getElementById("guardrail-export").disabled = true
  }

  function renderResults(report) {
    const panel = document.getElementById("guardrail-results-panel")
    panel.style.display = "block"
    document.getElementById("guardrail-empty-state").style.display = "none"

    renderer = new GuardrailReportRenderer(panel, {
      showChart: true,
      showToolbar: true,
      defaultSort: "severity"
    })
    renderer.render(report)
    document.getElementById("guardrail-export").disabled = false
  }

  function isSampleReport(key) {
    return REPORT_KEYS.includes(key)
  }

  function setInputSource(message) {
    const element = document.getElementById("input-source-note")
    if (element) element.textContent = message
  }

  async function loadSampleInput(key, loadId) {
    const fileName = SAMPLE_FILES[key]
    if (!fileName) return
    setInputSource(`Loading raw ${fileName} input...`)
    const response = await fetch(`${sampleBaseUrl}${fileName}`)
    if (!response.ok) throw new Error(`Could not load the raw ${key} sample input.`)
    const text = await response.text()
    if (loadId !== sampleLoadId) return
    sampleRawText = text
    document.getElementById("guardrail-input").value = text
    setInputSource(`Raw ${fileName} loaded from the committed sample. You can edit it before running Triage.`)
  }

  async function runPipeline(key, text, format, runId) {
    if (!isSampleReport(key) && !text.trim()) {
      throw new Error("Please provide report content to run triage.")
    }

    const steps = [
      ["parse", "Parsing in the browser", 250],
      ["context", "Preparing finding details", 250],
      ["compliance", "Matching known controls", 250],
      ["classify", "Applying local decision", 300],
      ["report", "Rendering report", 150]
    ]

    for (const [step, label, delay] of steps) {
      if (runId !== pipelineRunId) return
      setPipelineStep(step, label)
      setStatus(label)
      await new Promise((resolve) => setTimeout(resolve, delay))
    }

    if (runId !== pipelineRunId) return
    const unchangedSample = isSampleReport(key) && text === sampleRawText
    if (unchangedSample) {
      const response = await fetch(`${reportBaseUrl}${key}.json`)
      if (!response.ok) throw new Error(`Could not load the ${key} sample result.`)
      const report = await response.json()
      if (runId !== pipelineRunId) return
      renderResults(report)
      setStatus("Triage complete. This committed sample was produced by the Python pipeline.")
    } else {
      renderResults(normalizeResults(runTriage(parseReport(text, format))))
      setStatus("Triage complete. This browser result is a deterministic approximation. Select a row to inspect the decision.")
    }
    setPipelineStep("report", "Triage complete")
  }

  function exportReport() {
    if (!renderer?.report) return
    const report = renderer._originalReport || renderer.report
    const blob = new Blob([JSON.stringify({ ...report, exported_at: new Date().toISOString() }, null, 2)], { type: "application/json" })
    const url = URL.createObjectURL(blob)
    const link = document.createElement("a")
    link.href = url
    link.download = "guardrail-report.json"
    document.body.appendChild(link)
    link.click()
    link.remove()
    URL.revokeObjectURL(url)
  }

  function handleFile(file) {
    if (!file) return
    const reader = new FileReader()
    reader.onload = (event) => {
      const input = document.getElementById("guardrail-input")
      const sampleSelect = document.getElementById("guardrail-sample")
      input.value = event.target.result
      sampleSelect.value = ""
      sampleRawText = ""
      ++sampleLoadId
      ++pipelineRunId
      document.getElementById("guardrail-run").disabled = false
      document.getElementById("guardrail-run").removeAttribute("aria-busy")
      input.placeholder = "Paste SARIF, SonarQube JSON, or cppcheck XML"
      setInputSource(`Loaded ${file.name}. This report is ready for local browser parsing.`)
      const name = file.name.toLowerCase()
      document.getElementById("guardrail-format").value = name.endsWith(".xml") ? "cppcheck" : name.endsWith(".json") && input.value.includes('"issues"') ? "sonar" : "auto"
      setStatus(`Loaded ${file.name}. Review the raw report, then run Triage.`)
    }
    reader.readAsText(file)
  }

  ready(async () => {
    const input = document.getElementById("guardrail-input")
    const sampleSelect = document.getElementById("guardrail-sample")
    const formatSelect = document.getElementById("guardrail-format")
    const runButton = document.getElementById("guardrail-run")
    const resetButton = document.getElementById("guardrail-reset")
    const exportButton = document.getElementById("guardrail-export")
    const dropZone = document.getElementById("drop-zone")
    reportBaseUrl = window.GUARDRAIL_DEMO?.reportBaseUrl || ""
    sampleBaseUrl = window.GUARDRAIL_DEMO?.sampleBaseUrl || ""

    try {
      const response = await fetch(window.GUARDRAIL_DEMO?.rulesUrl || "../data/compliance-rules.json")
      if (!response.ok) throw new Error("Could not load compliance rules")
      complianceIndex = buildComplianceIndex(await response.json())
    } catch (error) {
      console.error(error)
      setStatus("Compliance mappings could not be loaded. The demo will continue without them.", true)
    }

    const updateSampleState = async () => {
      const key = sampleSelect.value
      const loadId = ++sampleLoadId
      ++pipelineRunId
      sampleRawText = ""
      runButton.disabled = false
      runButton.removeAttribute("aria-busy")
      input.value = ""
      input.placeholder = key ? "Loading raw sample input..." : "Paste SARIF, SonarQube JSON, or cppcheck XML"
      formatSelect.value = key === "cppcheck" ? "cppcheck" : key === "sonar" ? "sonar" : key ? "sarif" : "auto"
      if (!key) {
        setStatus("")
        setInputSource("Custom report input. The browser approximation will parse this text locally.")
        return
      }
      setStatus(`${sampleSelect.selectedOptions[0].textContent} selected. Loading the raw report...`)
      try {
        await loadSampleInput(key, loadId)
        if (loadId !== sampleLoadId) return
        setStatus(`${sampleSelect.selectedOptions[0].textContent} loaded. Review the raw report, then run Triage.`)
      } catch (error) {
        if (loadId !== sampleLoadId) return
        setInputSource("The raw sample could not be loaded. You can paste a report manually.")
        setStatus(error instanceof Error ? error.message : "Could not load the sample input.", true)
      }
    }

    await updateSampleState()
    sampleSelect.addEventListener("change", () => updateSampleState())

    resetButton.addEventListener("click", () => {
      sampleSelect.value = ""
      sampleRawText = ""
      ++sampleLoadId
      ++pipelineRunId
      runButton.disabled = false
      runButton.removeAttribute("aria-busy")
      input.value = ""
      input.placeholder = "Paste SARIF, SonarQube JSON, or cppcheck XML"
      formatSelect.value = "auto"
      setInputSource("Custom report input. The browser approximation will parse this text locally.")
      clearRenderedResults()
      setStatus("")
      resetPipeline()
    })

    runButton.addEventListener("click", async () => {
      clearRenderedResults()
      runButton.disabled = true
      runButton.setAttribute("aria-busy", "true")
      const runId = ++pipelineRunId
      try {
        await runPipeline(sampleSelect.value, input.value, formatSelect.value === "auto" ? undefined : formatSelect.value, runId)
      } catch (error) {
        if (runId !== pipelineRunId) return
        const message = error instanceof Error ? error.message : "Unable to process the report."
        if (!message.startsWith("Please provide") && !message.startsWith("Could not parse") && !message.startsWith("Unrecognized")) console.error(error)
        setStatus(message, true)
        resetPipeline()
      } finally {
        if (runId === pipelineRunId) {
          runButton.disabled = false
          runButton.removeAttribute("aria-busy")
        }
      }
    })

    exportButton.addEventListener("click", exportReport)

    for (const eventName of ["dragenter", "dragover", "dragleave", "drop"]) {
      dropZone.addEventListener(eventName, (event) => {
        event.preventDefault()
        event.stopPropagation()
      })
    }
    for (const eventName of ["dragenter", "dragover"]) {
      dropZone.addEventListener(eventName, () => dropZone.classList.add("drop-zone-active"))
    }
    for (const eventName of ["dragleave", "drop"]) {
      dropZone.addEventListener(eventName, () => dropZone.classList.remove("drop-zone-active"))
    }
    dropZone.addEventListener("drop", (event) => handleFile(event.dataTransfer.files[0]))

    const fileInput = document.createElement("input")
    fileInput.type = "file"
    fileInput.accept = ".sarif,.json,.xml"
    fileInput.hidden = true
    fileInput.addEventListener("change", (event) => {
      if (event.target.files?.[0]) handleFile(event.target.files[0])
      event.target.value = ""
    })
    document.body.appendChild(fileInput)

    dropZone.addEventListener("click", () => fileInput.click())
    dropZone.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault()
        fileInput.click()
      }
    })
  })
})()
